#include <bits/stdc++.h>
using namespace std;
#define int long long
signed main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
	int t;
	cin>>t;
	while(t--){
	    int n;
	    cin>>n;
	    int ts=3*n;
	    vector<int>a(ts);
	    for(int i=0;i<ts;i++)
	    {
	        cin>>a[i];
	    }
	    sort(a.rbegin(),a.rend());
	    int mx=0;
	   //for(int i=0;i<n;i++){
	   //     int x=a[3*i];
	   //     int y=a[3*i+1];
	   //     int z=a[3*i+2];
	   //     int cs=x+y-z;
	   //     if(cs>0){
	   //         mx+=cs;
	   //     }
	   // }
	   vector<int>p(ts+1,0);
	   for(int i=0;i<ts;i++){
	       p[i+1]=p[i]+a[i];
	   }
	   int ma=0;
	   for(int x=0;x<=n;x++){
	       int l=0,h=n-x;
	       while(l<h){
	           int m=l+(h-l)/2;
	           int v1=p[x+2*m]+3LL*p[3*n-2*x-m];
	           int v2=p[x+2*(m+1)]+3LL*p[3*n-2*x-(m+1)];
	           if(v1<v2){
	               l=m+1;
	           }
	           else{
	               h=m;
	           }
	       }
	       int cv=2LL*p[x]+p[x+2*l]+3LL*p[3*n-2*x-l];
	       ma=max(ma,cv);
	   
	   }
	   cout<<ma<<endl;
	   //for(int i=n;i<ts;i+=2){
	   //    mx+=a[i];
	   //}
	   // cout<<mx<<endl;
	}

}
